from datetime import date

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> {'borrowed_by': user, 'borrow_date': date} or None if available
        self.users = {}  # user -> {'current_book': book_id, 'unpaid_fines': float}

    def add_book(self, book_id: str) -> None:
        self.books[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user has unpaid fines and already holds a book
        if user in self.users and self.users[user]['unpaid_fines'] > 0:
            if self.users[user].get('current_book') is not None:
                raise ValueError(f"User {user} already holds a book")

        # Record the borrowing
        self.books[book_id] = {'borrowed_by': user, 'borrow_date': day}

        # Update user's record
        if user not in self.users:
            self.users[user] = {'current_book': book_id, 'unpaid_fines': 0.0}
        else:
            self.users[user]['current_book'] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        book_record = self.books[book_id]
        if book_record is None:
            raise ValueError(f"Book {book_id} is not currently borrowed")

        if book_record['borrowed_by'] != user:
            raise ValueError(f"User {user} did not borrow book {book_id}")

        # Calculate fine
        borrow_date = book_record['borrow_date']
        due_date = borrow_date.replace(day=borrow_date.day + self.loan_days)
        # Handle month/year overflow properly
        # Since we're only dealing with days, we'll use simple day difference calculation
        # Convert to ordinal dates for easy subtraction
        borrow_ordinal = borrow_date.toordinal()
        due_ordinal = borrow_ordinal + self.loan_days
        day_ordinal = day.toordinal()

        fine = 0.0
        if day_ordinal > due_ordinal:
            days_late = day_ordinal - due_ordinal
            fine = days_late * self.daily_fine

        # Update book status
        self.books[book_id] = None

        # Update user's record
        if user in self.users:
            self.users[user]['current_book'] = None
            self.users[user]['unpaid_fines'] += fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        if user not in self.users:
            return 0.0
        return self.users[user]['unpaid_fines']

    def pay(self, user: str) -> None:
        if user in self.users:
            self.users[user]['unpaid_fines'] = 0.0
